frappe.ui.form.on("Work Order", {

    onload(frm) {
        if (frm.doc.bom_no) {
            frappe.db.get_value("BOM", frm.doc.bom_no, "company", (r) => {
                if (r && r.company) {
                    frm.set_value("company", r.company);
                }
            });
        }
    },


    refresh(frm) {
        calculate_additional_cost(frm);
    }
});

frappe.ui.form.on("Additional Charge Amount", {
    amount(frm, cdt, cdn) {
        calculate_additional_cost(frm);
    },
    charges_type(frm, cdt, cdn) {
        calculate_additional_cost(frm);
    },
    custom_additional_charge_amount_remove(frm) {
        calculate_additional_cost(frm);
    },
    custom_additional_charge_amount_add(frm) {
        calculate_additional_cost(frm);
    }
});

function calculate_additional_cost(frm) {
    let total = 0;

    if (frm.doc.custom_additional_charge_amount) {
        frm.doc.custom_additional_charge_amount.forEach(row => {
            total += flt(row.amount);
        });
    }

    frm.set_value("additional_operating_cost", total);
    frm.refresh_field("additional_operating_cost");
}

frappe.ui.form.on('Delivery Note', {
    refresh: function(frm) {

        if (!frm.is_new()
            && frm.doc.custom_risk_and_reward === "Company") {

            frm.add_custom_button(__('Create Shipment'), function () {

                frappe.call({
                    method: "frappe.client.get",
                    args: {
                        doctype: "Delivery Note",
                        name: frm.doc.name
                    },
                    callback: function(r) {
                        if (!r.message) return;

                        let dn = r.message;

                        // ✅ Create new Shipment
                        frappe.new_doc('Shipment', {
                            delivery_customer: dn.customer,
                            company: dn.company,
                            value_of_goods:dn.grand_total
                        }, doc => {
                            // ✅ After doc is created, add child row with grand_total
                            let row = frappe.model.add_child(doc, 'Shipment Delivery Note', 'shipment_delivery_note');
                            row.delivery_note = dn.name;
                            row.grand_total = dn.total;  // ✅ Use grand_total instead of total

                            // ✅ Refresh child table to show the data
                            frm.fields_dict['shipment_delivery_note'].grid.refresh();
                        });

                    }
                });

            }, __('Create'));

        }
    }
});


